  ('abb-1svr730885r1300', '1SVR730885R1300', '1SVR730885R1300', 'ABB CM-MPS.11S Three-phase monitoring relay 2c/o, 0,0.1-30s, L1-L2-L3-N=3x90-170VAC', 'ABB', 'Switchgear', 'The CM-MPS.11S is a multifunctional relay from the CM three-phase monitors range. It operates with a rated control supply voltage / three-phase measuring voltage of 90-170 V AC 50/60 Hz and has a 2 c/o (SPDT) output with contacts rated at 250 V / 4 A. This relay is also suitable to monitor single-phase mains. It monitors all phase parameters such as over/undervoltage, phase unbalance, phase failur', 14596, 14304, 'pc', 'https://shop.in.abb.com/media/catalog/product/6/3/63b489bd5da1c0.56583596.jpg', true, true, 11823),
  ('abb-1svr730774r3300', '1SVR730774R3300', '1SVR730774R3300', 'ABB CM-PAS.41S Three-phase monitoring relay 2c/o, 0,0.1-30s, L1-L2-L3=3x300-500VAC', 'ABB', 'Switchgear', 'The CM-PAS.41S relay is from the CM three-phase monitors range. This relay operates with a rated control supply voltage / three-phase measuring voltage of 300-500 V AC and has a 2 c/o output with contacts rated at 250 V / 4 A. The CM-PAS.41S monitors the phase parameters phase failure, phase sequence and phase unbalance. An ON-delay is adjustable over a range of instantaneous to 30 s (0, 0.1-30 s)', 14291, 14005, 'pc', 'https://shop.in.abb.com/media/catalog/product/6/3/63b489c66cb2b6.87092087.jpg', true, true, 11824),
